const matBlackFill = new THREE.MeshBasicMaterial({ color: 0x111111 });
const matBlue = new THREE.MeshBasicMaterial({ color: COL.blue, side: THREE.DoubleSide });
const matBlueLine = new THREE.LineBasicMaterial({ color: COL.blueLine });
const matSweep = new THREE.MeshBasicMaterial({ color: COL.sweep });
