function samp(fn, n) { const a = []; for (let i = 0; i <= n; i++) a.push(fn(i / n)); return a; }
function arrowTo(from, to, headLen = 0.24, headR = 0.075, lineMat = matBlack, fillMat = matBlackFill) {
