/* ---------- state --------------------------------------------------------- */
const params = {
  rho: 2.4, dRho: 0.35,
  phi: THREE.MathUtils.degToRad(42), dPhi: 0.28,
  theta: THREE.MathUtils.degToRad(50), dTheta: 0.30
};
let labelMode = 'both', focus = null, labelsReady = false;
let hiTubes = { rho: [], phi: [], theta: [] };
const A = {};                       // anchors for labels
const INSET_W = scr(5.25, 0.95, 0); // inset centre (world)

/* ---------- rebuild ------------------------------------------------------- */
function rebuild() {
  const { rho, dRho, phi, dPhi, theta, dTheta } = params;
  const r0 = rho, r1 = rho + dRho, p0 = phi, p1 = phi + dPhi, t0 = theta, t1 = theta + dTheta;
  const rc = (r0 + r1) / 2, pc = (p0 + p1) / 2, tc = (t0 + t1) / 2;

  [gGeom, gAnnIn, gAnnOut, gInset].forEach(clearGroup);
  _interactiveObjects.length = 0;
  hiTubes = { rho: [], phi: [], theta: [] };

  /* --- in-place box --- */
  const mesh = new THREE.Mesh(boxGeom(r0, r1, p0, p1, t0, t1, 12), [matBase, matTop, matSide]);
  gGeom.add(mesh);
  gGeom.add(new THREE.LineSegments(boxEdgeGeom(r0, r1, p0, p1, t0, t1, 24), matEdge));

  /* --- labelled edges (clickable tubes), in place --- */
  const edgeFns = {
    rho: u => sphPt(LERP(r0, r1, u), p0, t0),
    phi: u => sphPt(r1, LERP(p0, p1, u), t0),
    theta: u => sphPt(r1, p0, LERP(t0, t1, u))
  };
  const edgeInfo = {
    rho: { title: 'Radial edge: Δρ', body: 'Moving out along ρ with φ and θ fixed traces a straight segment whose length is exactly Δρ — ρ is measured in distance units, so no extra factor appears.' },
    phi: { title: 'Polar edge: ρΔφ', body: 'Changing φ with ρ and θ fixed traces an arc of the circle of radius ρ, so the edge length is ρΔφ. The same angle gives a longer edge farther from the origin.' },
    theta: { title: 'Azimuthal edge: ρ sin φ Δθ', body: 'Changing θ sweeps the point around the z-axis on a circle of radius ρ sin φ (its distance from the axis), so the edge length is ρ sin φ Δθ — it collapses near the poles.' }
  };
  for (const k of ['rho', 'phi', 'theta']) {
    const tube = tubeAlong(edgeFns[k], 0.030, focus === k ? matTubeH : matTubeN);
    gGeom.add(tube); hiTubes[k].push(tube);
    registerInteractive(tube, {
      title: edgeInfo[k].title, body: edgeInfo[k].body,
      tooltip: edgeInfo[k].title + ' — click to highlight',
      onClick: () => setFocus(k)
    });
  }

  /* --- dashed meridian arcs at r0 and r1 --- */
  for (const r of [r0, r1]) {
    gGeom.add(dashFrom(samp(u => sphPt(r, LERP(0.015, Math.PI / 2 - 0.01, u), t0), 70), matDash));
  }
  /* --- dashed φ rays through both cone faces --- */
  for (const p of [p0, p1]) {
    gGeom.add(dashFrom(samp(u => sphPt(LERP(0.05, 3.75, u), p, t0), 2), matDash));
  }
  /* --- dashed θ rays in the xy-plane through the patch --- */
  for (const t of [t0, t1]) {
    gGeom.add(dashFrom(samp(u => M3(LERP(0.05, 3.1, u) * Math.cos(t), LERP(0.05, 3.1, u) * Math.sin(t), 0), 2), matDash));
  }

  /* --- blue projection patch (projection of the φ = φ0 face) --- */
  const a0 = r0 * Math.sin(p0), b0 = r1 * Math.sin(p0);
  gGeom.add(new THREE.Mesh(patchGeom(a0, b0, t0, t1, 14), matBlue));
  const outline = []
    .concat(samp(u => M3(a0 * Math.cos(LERP(t0, t1, u)), a0 * Math.sin(LERP(t0, t1, u)), 0.01), 14))
    .concat(samp(u => M3(b0 * Math.cos(LERP(t1, t0, u)), b0 * Math.sin(LERP(t1, t0, u)), 0.01), 14).reverse());
  const ring = samp(u => M3(a0 * Math.cos(LERP(t0, t1, u)), a0 * Math.sin(LERP(t0, t1, u)), 0.01), 14)
    .concat(samp(u => M3(b0 * Math.cos(LERP(t1, t0, u)), b0 * Math.sin(LERP(t1, t0, u)), 0.01), 14));
  ring.push(ring[0]);
  gGeom.add(lineFrom(ring, matBlueLine));

  /* --- drop lines from the p0 face corners to the patch corners --- */
  for (const r of [r0, r1]) for (const t of [t0, t1]) {
    const top = sphPt(r, p0, t);
    const bot = M3(r * Math.sin(p0) * Math.cos(t), r * Math.sin(p0) * Math.sin(t), 0);
    gGeom.add(dashFrom([top, bot], matDashF));
  }

  /* ===== in-place annotations ===== */
  /* Δρ bracket on the z-axis */
  const yb = -0.55, ybc = -0.46;
  gAnnIn.add(lineFrom([M3(0, 0, r0), M3(0, yb, r0)], matBlack));
  gAnnIn.add(lineFrom([M3(0, 0, r1), M3(0, yb, r1)], matBlack));
  gAnnIn.add(lineFrom([M3(0, ybc, r0), M3(0, ybc, r1)], matBlack));
  A.dRho = M3(0, ybc, rc);

  /* Δφ arc at the origin */
  gAnnIn.add(lineFrom(samp(u => sphPt(1.05, LERP(p0, p1, u), t0), 24), matBlack));
  A.dPhi = sphPt(1.05, pc, t0);

  /* Δθ arc in the xy-plane */
  gAnnIn.add(lineFrom(samp(u => {
    const t = LERP(t0, t1, u); return M3(0.95 * Math.cos(t), 0.95 * Math.sin(t), 0);
  }, 20), matBlack));
  A.dTheta = M3(0.95 * Math.cos(tc), 0.95 * Math.sin(tc), 0);

  /* ρ sin φ bracket in the xy-plane */
  const tb = t0 - 0.13;
  const O = M3(0, 0, 0), E = M3(a0 * Math.cos(tb), a0 * Math.sin(tb), 0);
  gAnnIn.add(lineFrom([O, E], matBlack));
  gAnnIn.add(lineFrom([O, M3(0, 0, -0.001).add(new THREE.Vector3(0, 0.2, 0))], matBlack));
  gAnnIn.add(lineFrom([E, E.clone().add(new THREE.Vector3(0, 0.2, 0))], matBlack));
  A.rsp = O.clone().lerp(E, 0.5);

  /* leader arrow into the blue patch */
  const rm = (a0 + b0) / 2;
  const patchC = M3(rm * Math.cos(tc), rm * Math.sin(tc), 0.02);
  const leadStart = patchC.clone().add(M3(-1.45, 0.35, 0.18));
  gAnnIn.add(arrowTo(leadStart, patchC, 0.22, 0.07));
  A.rspdt = leadStart;

  /* ρΔφ bracket on the outer φ-edge of the box */
  gAnnIn.add(lineFrom([sphPt(r1, p0, t0), sphPt(r1 + 0.32, p0, t0)], matBlack));
  gAnnIn.add(lineFrom([sphPt(r1, p1, t0), sphPt(r1 + 0.32, p1, t0)], matBlack));
  gAnnIn.add(lineFrom(samp(u => sphPt(r1 + 0.24, LERP(p0, p1, u), t0), 16), matBlack));
  A.rdphi = sphPt(r1 + 0.30, pc, t0);

  /* ===== enlarged inset ===== */
  const centre = sphPt(rc, pc, tc);
  const corner = sphPt(r1, p0, t0);
  const rad = Math.max(0.18, corner.distanceTo(centre)) * 1.15;
  const S = THREE.MathUtils.clamp(1.55 / rad, 1.4, 5.0);
  gInset.position.copy(INSET_W);
  gInset.scale.setScalar(S);
  const inner = new THREE.Group();
  inner.position.copy(centre).multiplyScalar(-1);
  gInset.add(inner);
  inner.add(new THREE.Mesh(boxGeom(r0, r1, p0, p1, t0, t1, 12), [matBase, matTop, matSide]));
  inner.add(new THREE.LineSegments(boxEdgeGeom(r0, r1, p0, p1, t0, t1, 24), matEdge));
  for (const k of ['rho', 'phi', 'theta']) {
    const tube = tubeAlong(edgeFns[k], 0.030, focus === k ? matTubeH : matTubeN);
    inner.add(tube); hiTubes[k].push(tube);
    registerInteractive(tube, {
      title: edgeInfo[k].title, body: edgeInfo[k].body,
      tooltip: edgeInfo[k].title + ' — click to highlight',
      onClick: () => setFocus(k)
    });
  }
  const iw = (p) => p.clone().sub(centre).multiplyScalar(S).add(INSET_W);

  /* inset leader arrows */
  const mRho = iw(edgeFns.rho(0.5)), mPhi = iw(edgeFns.phi(0.5)), mThe = iw(edgeFns.theta(0.5));
  A.iRho = mRho.clone().addScaledVector(SR, -2.05).addScaledVector(SU, 0.15);
  A.iPhi = mPhi.clone().addScaledVector(SR, -1.55).addScaledVector(SU, 1.05);
  A.iThe = mThe.clone().addScaledVector(SR, 1.05).addScaledVector(SU, 1.55);
  gAnnOut.add(arrowTo(A.iRho.clone().addScaledVector(SR, 0.45), mRho, 0.24, 0.075));
  gAnnOut.add(arrowTo(A.iPhi.clone().addScaledVector(SR, 0.40).addScaledVector(SU, -0.18), mPhi, 0.24, 0.075));
  gAnnOut.add(arrowTo(A.iThe.clone().addScaledVector(SR, -0.25).addScaledVector(SU, -0.35), mThe, 0.24, 0.075));
  A.cap = INSET_W.clone().addScaledVector(SU, -2.15);

  if (labelsReady) syncLabelPositions();
  updateReadout();
}

/* ---------- labels -------------------------------------------------------- */
const focusable = [];
function mkFocusLabel(base, pos, key, opt) {
  const e = addLabel(base, pos, opt);
  e.base = base; e.fkey = key; focusable.push(e);
  return e;
}
const LB = {};
function mkLabels() {
  LB.x = addLabel('<i>x</i>', M3(AX + 0.28, 0, 0), { bold: true, fontSize: '15px', offset: [-2, 12] });
  LB.y = addLabel('<i>y</i>', M3(0, AX + 0.28, 0), { bold: true, fontSize: '15px', offset: [4, 12] });
  LB.z = addLabel('<i>z</i>', M3(0, 0, AX + 0.28), { bold: true, fontSize: '15px', offset: [-10, -2] });

  LB.dRho = mkFocusLabel('Δρ', A.dRho, 'rho', { fontSize: '13px', offset: [-22, 0] });
  LB.dPhi = addLabel('Δφ', A.dPhi, { fontSize: '13px', offset: [-26, -6] });
  LB.dTheta = addLabel('Δθ', A.dTheta, { fontSize: '13px', offset: [-30, 4] });
  LB.rsp = addLabel('ρ sin φ', A.rsp, { fontSize: '13px', offset: [-6, 22] });
  LB.rspdt = mkFocusLabel('ρ sin φ Δθ', A.rspdt, 'theta', { fontSize: '13px', offset: [26, -10] });
  LB.rdphi = mkFocusLabel('ρΔφ', A.rdphi, 'phi', { fontSize: '13px', offset: [26, -8] });

  LB.iRho = mkFocusLabel('Δρ', A.iRho, 'rho', { fontSize: '13px', offset: [-20, 0] });
  LB.iPhi = mkFocusLabel('ρΔφ', A.iPhi, 'phi', { fontSize: '13px', offset: [-22, -6] });
  LB.iThe = mkFocusLabel('ρ sin φ Δθ', A.iThe, 'theta', { fontSize: '13px', offset: [16, -12] });

  LB.cap = addLabel(captionHTML(), A.cap, { fontSize: '14px' });

  LB.inPlace = [LB.dRho, LB.dPhi, LB.dTheta, LB.rsp, LB.rspdt, LB.rdphi];
  LB.inset = [LB.iRho, LB.iPhi, LB.iThe];
  labelsReady = true;
}
function syncLabelPositions() {
  LB.dRho.pos.copy(A.dRho); LB.dPhi.pos.copy(A.dPhi); LB.dTheta.pos.copy(A.dTheta);
  LB.rsp.pos.copy(A.rsp); LB.rspdt.pos.copy(A.rspdt); LB.rdphi.pos.copy(A.rdphi);
  LB.iRho.pos.copy(A.iRho); LB.iPhi.pos.copy(A.iPhi); LB.iThe.pos.copy(A.iThe);
  LB.cap.pos.copy(A.cap);
}
function captionHTML() {
  const b = (k, s) => (focus === k ? `<b style="color:${HIC}">${s}</b>` : s);
  return `Δ<i>V</i> = ρ<sup>2</sup> sin φ ${b('rho', 'Δρ')} ${b('phi', 'Δφ')} ${b('theta', 'Δθ')}`;
}
function refreshLabelStyles() {
  for (const e of focusable) {
    e.div.innerHTML = (e.fkey === focus)
      ? `<b style="color:${HIC}">${e.base}</b>` : e.base;
  }
  if (LB.cap) LB.cap.div.innerHTML = captionHTML();
}

/* ---------- label mode / focus ------------------------------------------- */
function applyLabelMode() {
  const showIn = labelMode !== 'inset';
  const showOut = labelMode !== 'place';
  gAnnIn.visible = showIn;
  gAnnOut.visible = showOut;
  if (!labelsReady) return;
  LB.inPlace.forEach(e => e.div.style.visibility = showIn ? 'visible' : 'hidden');
  LB.inset.forEach(e => e.div.style.visibility = showOut ? 'visible' : 'hidden');
  document.getElementById('lmPlace').classList.toggle('active', labelMode === 'place');
  document.getElementById('lmInset').classList.toggle('active', labelMode === 'inset');
  document.getElementById('lmBoth').classList.toggle('active', labelMode === 'both');
}
function setFocus(k) {
  focus = (focus === k || k === null) ? (k === null ? null : null) : k;
  if (k !== null && focus !== k) focus = null; // toggle off on second click
  for (const key of ['rho', 'phi', 'theta']) {
    const on = focus === key;
    hiTubes[key].forEach(m => { m.material = on ? matTubeH : matTubeN; });
  }
  document.querySelectorAll('#ui button[data-edge]').forEach(b =>
    b.classList.toggle('active', b.dataset.edge === (focus || 'none')));
  refreshLabelStyles();
}

/* ---------- readout ------------------------------------------------------- */
function updateReadout() {
  const { rho, dRho, phi, dPhi, dTheta } = params;
  const eR = dRho, eP = rho * dPhi, eT = rho * Math.sin(phi) * dTheta;
  const el = document.getElementById('readout');
  if (!el) return;
  el.innerHTML =
    `ρ = ${rho.toFixed(2)}, φ = ${(phi * 180 / Math.PI).toFixed(0)}°<br>` +
    `Δρ = <b>${eR.toFixed(3)}</b> &nbsp; ρΔφ = <b>${eP.toFixed(3)}</b><br>` +
    `ρ sin φ Δθ = <b>${eT.toFixed(3)}</b><br>` +
    `ΔV ≈ ${(eR * eP * eT).toFixed(4)}`;
}

