──────────────────────────────────────────────────────────────────────────── */

/* ---------- camera basis solved from the source's measured axis angles ----- */
/* math x drawn 30° below horizontal-left, math y 20° below horizontal-right.  */
const AXA = { x: 20, z: 30 };                 // scaffold: angles.x = world X (= math y)
const _tx = Math.tan(THREE.MathUtils.degToRad(AXA.x));
const _tz = Math.tan(THREE.MathUtils.degToRad(AXA.z));
const EL = Math.asin(Math.sqrt(_tx * _tz));
const AZ = Math.atan(Math.sqrt(_tz / _tx));
const SR = new THREE.Vector3(Math.sin(AZ), 0, -Math.cos(AZ));                       // screen right
const SU = new THREE.Vector3(-Math.cos(AZ) * Math.sin(EL), Math.cos(EL), -Math.sin(AZ) * Math.sin(EL)); // screen up
const CAMDIR = new THREE.Vector3(Math.cos(AZ) * Math.cos(EL), Math.sin(EL), Math.sin(AZ) * Math.cos(EL));
const scr = (sx, sy, dep = 0) => new THREE.Vector3()
  .addScaledVector(SR, sx).addScaledVector(SU, sy).addScaledVector(CAMDIR, dep);

/* ---------- math → world (math z is up; math x → lower-left) -------------- */
const M3 = (x, y, z) => new THREE.Vector3(y, z, x);
function sphPt(r, p, t) {
  const s = Math.sin(p);
  return M3(r * s * Math.cos(t), r * s * Math.sin(t), r * Math.cos(p));
}
const LERP = (a, b, u) => a + (b - a) * u;

/* ---------- layout (screen units) ----------------------------------------- */
const AX = 3.15;                       // axis length
const IN_SX = 4.50, IN_SY = 1.75;      // inset centre on screen
const IN_DEPTH = 2.0, IN_RAD = 1.45;   // inset pushed toward camera, target half-size
const INSET_W = scr(IN_SX, IN_SY, IN_DEPTH);

/* ---------- palette & materials ------------------------------------------- */
const COL = {
  base: 0xF0A37A, top: 0xF6C4A6, side: 0xE8895F, edge: 0xE2601F,
  blue: 0x2E4B8C, blueLine: 0x1B3468, gray: 0x7A7A7A, sweep: 0xB3B3B3, hi: 0x14A44D
};
const HIC = '#14A44D';
const mkFace = (c) => new THREE.MeshBasicMaterial({
  color: c, transparent: true, opacity: 0.9, side: THREE.DoubleSide,
  polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
});
const matBase = mkFace(COL.base), matTop = mkFace(COL.top), matSide = mkFace(COL.side);
const matEdge = new THREE.LineBasicMaterial({ color: COL.edge });
const matDash = new THREE.LineDashedMaterial({ color: COL.gray, dashSize: 0.15, gapSize: 0.10 });
const matDashF = new THREE.LineDashedMaterial({ color: COL.gray, dashSize: 0.10, gapSize: 0.10, transparent: true, opacity: 0.65 });
const matBlack = new THREE.LineBasicMaterial({ color: 0x111111 });
const matBlackFill = new THREE.MeshBasicMaterial({ color: 0x111111 });
const matBlue = new THREE.MeshBasicMaterial({ color: COL.blue, side: THREE.DoubleSide });
const matBlueLine = new THREE.LineBasicMaterial({ color: COL.blueLine });
const matSweep = new THREE.MeshBasicMaterial({ color: COL.sweep });
const matTubeN = new THREE.MeshBasicMaterial({ color: COL.edge });
const matTubeH = new THREE.MeshBasicMaterial({ color: COL.hi });

/* ---------- builders ------------------------------------------------------- */
function lineFrom(pts, mat) { return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat); }
function dashFrom(pts, mat) { const l = lineFrom(pts, mat); l.computeLineDistances(); return l; }
function samp(fn, n) { const a = []; for (let i = 0; i <= n; i++) a.push(fn(i / n)); return a; }
function arrowTo(from, to, headLen = 0.22, headR = 0.068, lineMat = matBlack, fillMat = matBlackFill) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length(); if (len < 1e-6) return g;
  dir.normalize();
  g.add(lineFrom([from, to.clone().addScaledVector(dir, -headLen * 0.9)], lineMat));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 16), fillMat);
  cone.position.copy(to).addScaledVector(dir, -headLen / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  g.add(cone);
  return g;
}
function leader(anchor, target, gap = 0.34) {
  const dir = new THREE.Vector3().subVectors(target, anchor).normalize();
  return arrowTo(anchor.clone().addScaledVector(dir, gap), target);
}
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const c = g.children[i]; g.remove(c);
    c.traverse(o => { if (o.geometry) o.geometry.dispose(); });
  }
}
function boxGeom(r0, r1, p0, p1, t0, t1, N) {
  const pos = [], groups = [];
  const faces = [
    [(u, v) => sphPt(r0, LERP(p0, p1, u), LERP(t0, t1, v)), 0],
    [(u, v) => sphPt(r1, LERP(p0, p1, u), LERP(t0, t1, v)), 0],
    [(u, v) => sphPt(LERP(r0, r1, u), p0, LERP(t0, t1, v)), 1],
    [(u, v) => sphPt(LERP(r0, r1, u), p1, LERP(t0, t1, v)), 0],
    [(u, v) => sphPt(LERP(r0, r1, u), LERP(p0, p1, v), t0), 2],
    [(u, v) => sphPt(LERP(r0, r1, u), LERP(p0, p1, v), t1), 0]
  ];
  for (const [f, mi] of faces) {
    const start = pos.length / 3;
    for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
      const a = f(i / N, j / N), b = f((i + 1) / N, j / N), c = f((i + 1) / N, (j + 1) / N), e = f(i / N, (j + 1) / N);
      pos.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z, a.x, a.y, a.z, c.x, c.y, c.z, e.x, e.y, e.z);
    }
    groups.push([start, pos.length / 3 - start, mi]);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  groups.forEach(([s, c, m]) => g.addGroup(s, c, m));
  g.computeVertexNormals();
  return g;
}
function boxEdgeGeom(r0, r1, p0, p1, t0, t1, N) {
  const seg = [];
  const push = (fn) => { let pr = fn(0); for (let i = 1; i <= N; i++) { const cu = fn(i / N); seg.push(pr.x, pr.y, pr.z, cu.x, cu.y, cu.z); pr = cu; } };
  for (const r of [r0, r1]) for (const t of [t0, t1]) push(u => sphPt(r, LERP(p0, p1, u), t));
  for (const r of [r0, r1]) for (const p of [p0, p1]) push(u => sphPt(r, p, LERP(t0, t1, u)));
  for (const p of [p0, p1]) for (const t of [t0, t1]) push(u => sphPt(LERP(r0, r1, u), p, t));
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(seg, 3));
  return g;
}
function patchGeom(a, b, t0, t1, N) {
  const pos = [], P = (r, t) => M3(r * Math.cos(t), r * Math.sin(t), 0.006);
  for (let j = 0; j < N; j++) {
    const tA = LERP(t0, t1, j / N), tB = LERP(t0, t1, (j + 1) / N);
    const p1 = P(a, tA), p2 = P(b, tA), p3 = P(b, tB), p4 = P(a, tB);
    pos.push(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z, p3.x, p3.y, p3.z,
      p1.x, p1.y, p1.z, p3.x, p3.y, p3.z, p4.x, p4.y, p4.z);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  return g;
}
function tubeAlong(fn, radius, mat) {
  const curve = new THREE.CatmullRomCurve3(samp(fn, 18));
  return new THREE.Mesh(new THREE.TubeGeometry(curve, 26, radius, 8, false), mat);
}

/* ---------- framing: collect the true screen-space extent ------------------ */
/* The scene AABB is useless here (content runs along a diagonal), so the view
   is fitted from an explicit list of layout points projected on (SR, SU).     */
const framePts = [];
const addFrame = (p) => { framePts.push(p.clone()); return p; };

/* ---------- static axes ---------------------------------------------------- */
const gStatic = new THREE.Group(); scene.add(gStatic);
[M3(AX, 0, 0), M3(0, AX, 0), M3(0, 0, AX)].forEach((end) => {
  const dir = end.clone().normalize();
  gStatic.add(lineFrom([new THREE.Vector3(0, 0, 0), end.clone().addScaledVector(dir, -0.2)], matBlack));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.24, 16), matBlackFill);
  cone.position.copy(end).addScaledVector(dir, -0.12);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  gStatic.add(cone);
  addFrame(end.clone().multiplyScalar(1.1));
});
gStatic.add(new THREE.Mesh(new THREE.SphereGeometry(0.045, 12, 10), matBlackFill));
addFrame(new THREE.Vector3(0, 0, 0));

/* ---------- groups --------------------------------------------------------- */
const gGeom = new THREE.Group(); scene.add(gGeom);     // boxes / guides / patch
const gAnnIn = new THREE.Group(); scene.add(gAnnIn);   // in-place annotations
const gAnnOut = new THREE.Group(); scene.add(gAnnOut); // inset annotations
const gInset = new THREE.Group(); scene.add(gInset);   // enlarged copy
const gSweep = new THREE.Group(); scene.add(gSweep);   // gray sweep arrow

/* gray sweep arrow: above the in-place box, up and over, head down-right */
(function () {
  const a = scr(1.15, 2.30, 2.6), c = scr(2.55, 3.25, 2.6), b = scr(3.40, 2.62, 2.6);
  const curve = new THREE.QuadraticBezierCurve3(a, c, b);
  gSweep.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 48, 0.085, 10, false), matSweep));
  const tan = curve.getTangent(1).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.25, 0.60, 18), matSweep);
  head.position.copy(b).addScaledVector(tan, 0.2);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  gSweep.add(head);
  [a, c, b].forEach(addFrame);
  addFrame(scr(3.7, 2.9, 0));
})();

/* inset + caption extents for framing */
addFrame(scr(IN_SX - 2.05, IN_SY - 1.60));
addFrame(scr(IN_SX + 1.95, IN_SY + 1.70));
addFrame(scr(IN_SX + 0.9, IN_SY - 2.15));   // caption line

/* ---------- state ---------------------------------------------------------- */
const params = {
  rho: 2.4, dRho: 0.35,
  phi: THREE.MathUtils.degToRad(42), dPhi: 0.28,
  theta: THREE.MathUtils.degToRad(50), dTheta: 0.30
};
let labelMode = 'both', focus = null, labelsReady = false, tween = null;
let hiTubes = { rho: [], phi: [], theta: [] };
const A = {};   // label anchors

/* moderate growth of the box counted into the frame so steps stay on screen */
for (const rr of [params.rho, params.rho + 0.7])
  for (const pp of [params.phi, params.phi + 0.45])
    for (const tt of [params.theta, params.theta + 0.45])
      addFrame(sphPt(rr + 0.35, pp, tt));

/* ---------- rebuild -------------------------------------------------------- */
function rebuild() {
  const { rho, dRho, phi, dPhi, theta, dTheta } = params;
  const r0 = rho, r1 = rho + dRho, p0 = phi, p1 = phi + dPhi, t0 = theta, t1 = theta + dTheta;
  const rc = (r0 + r1) / 2, pc = (p0 + p1) / 2, tc = (t0 + t1) / 2;

  [gGeom, gAnnIn, gAnnOut, gInset].forEach(clearGroup);
  _interactiveObjects.length = 0;
  hiTubes = { rho: [], phi: [], theta: [] };

  /* --- in-place curved box --- */
  gGeom.add(new THREE.Mesh(boxGeom(r0, r1, p0, p1, t0, t1, 11), [matBase, matTop, matSide]));
  gGeom.add(new THREE.LineSegments(boxEdgeGeom(r0, r1, p0, p1, t0, t1, 22), matEdge));

  /* --- the three labelled edges (clickable) --- */
  const edgeFns = {
    rho: u => sphPt(LERP(r0, r1, u), p0, t0),
    phi: u => sphPt(r1, LERP(p0, p1, u), t0),
    theta: u => sphPt(r1, p0, LERP(t0, t1, u))
  };
  const edgeInfo = {
    rho: { title: 'Radial edge: Δρ', body: 'Moving outward along ρ with φ and θ fixed traces a straight segment of length exactly Δρ — ρ is measured in distance units, so no extra factor appears.' },
    phi: { title: 'Polar edge: ρΔφ', body: 'Changing φ with ρ and θ fixed traces an arc of the circle of radius ρ, so the edge length is ρΔφ. The same angle gives a longer edge farther from the origin.' },
    theta: { title: 'Azimuthal edge: ρ sin φ Δθ', body: 'Changing θ sweeps the point around the z-axis on a circle of radius ρ sin φ (its distance from the axis), so the edge length is ρ sin φ Δθ — it collapses near the poles.' }
  };
  for (const k of ['rho', 'phi', 'theta']) {
    const tube = tubeAlong(edgeFns[k], 0.030, focus === k ? matTubeH : matTubeN);
    gGeom.add(tube); hiTubes[k].push(tube);
    registerInteractive(tube, {
      title: edgeInfo[k].title, body: edgeInfo[k].body,
      tooltip: edgeInfo[k].title + ' — click to highlight',
      onClick: () => setFocus(focus === k ? null : k)
    });
  }

  /* --- dashed meridian arcs at r0 and r1 (θ = t0 plane) --- */
  for (const r of [r0, r1])
    gGeom.add(dashFrom(samp(u => sphPt(r, LERP(0.02, Math.PI / 2 - 0.01, u), t0), 70), matDash));
  /* --- dashed φ rays through both cone faces --- */
  for (const p of [p0, p1])
    gGeom.add(dashFrom(samp(u => sphPt(LERP(0.05, 3.25, u), p, t0), 2), matDash));
  /* --- dashed θ rays in the xy-plane through the patch --- */
  for (const t of [t0, t1])
    gGeom.add(dashFrom(samp(u => M3(LERP(0.05, 2.65, u) * Math.cos(t), LERP(0.05, 2.65, u) * Math.sin(t), 0), 2), matDash));

  /* --- blue projection patch --- */
  const a0 = r0 * Math.sin(p0), b0 = r1 * Math.sin(p0);
  gGeom.add(new THREE.Mesh(patchGeom(a0, b0, t0, t1, 14), matBlue));
  const ring = samp(u => M3(a0 * Math.cos(LERP(t0, t1, u)), a0 * Math.sin(LERP(t0, t1, u)), 0.012), 14)
    .concat(samp(u => M3(b0 * Math.cos(LERP(t1, t0, u)), b0 * Math.sin(LERP(t1, t0, u)), 0.012), 14));
  ring.push(ring[0]);
  gGeom.add(lineFrom(ring, matBlueLine));

  /* --- drop lines from the φ0 face corners onto the patch corners --- */
  for (const r of [r0, r1]) for (const t of [t0, t1]) {
    gGeom.add(dashFrom([sphPt(r, p0, t),
      M3(r * Math.sin(p0) * Math.cos(t), r * Math.sin(p0) * Math.sin(t), 0)], matDashF));
  }

  /* ===== in-place annotations ===== */
  const LEFT = SR.clone().multiplyScalar(-1);            // screen-left, world direction

  /* Δρ bracket on the z-axis */
  const zIn = M3(0, 0, r0), zOut = M3(0, 0, r1);
  gAnnIn.add(lineFrom([zIn, zIn.clone().addScaledVector(LEFT, 0.60)], matBlack));
  gAnnIn.add(lineFrom([zOut, zOut.clone().addScaledVector(LEFT, 0.60)], matBlack));
  gAnnIn.add(lineFrom([zIn.clone().addScaledVector(LEFT, 0.50), zOut.clone().addScaledVector(LEFT, 0.50)], matBlack));
  A.dRho = M3(0, 0, rc).addScaledVector(LEFT, 0.62);

  /* Δφ arc at the origin, between the two φ rays */
  gAnnIn.add(lineFrom(samp(u => sphPt(1.15, LERP(p0, p1, u), t0), 26), matBlack));
  A.dPhi = sphPt(1.15, pc, t0);

  /* Δθ arc in the xy-plane + short leader to its label */
  const arcT = samp(u => { const t = LERP(t0, t1, u); return M3(1.0 * Math.cos(t), 1.0 * Math.sin(t), 0); }, 22);
  gAnnIn.add(lineFrom(arcT, matBlack));
  const tMid = M3(1.0 * Math.cos(tc), 1.0 * Math.sin(tc), 0);
  A.dTheta = tMid.clone().addScaledVector(LEFT, 0.95);
  gAnnIn.add(lineFrom([A.dTheta.clone().addScaledVector(SR, 0.22), tMid], matBlack));

  /* ρ sin φ bracket in the xy-plane */
  const tb = t0 - 0.16;
  const O = M3(0, 0, 0), E = M3(a0 * Math.cos(tb), a0 * Math.sin(tb), 0);
  const up = new THREE.Vector3(0, 0.20, 0);
  gAnnIn.add(lineFrom([O, E], matBlack));
  gAnnIn.add(lineFrom([O, O.clone().add(up)], matBlack));
  gAnnIn.add(lineFrom([E, E.clone().add(up)], matBlack));
  A.rsp = O.clone().lerp(E, 0.5);
  addFrame(A.rsp.clone().addScaledVector(SU, -0.5));

  /* leader arrow into the blue patch */
  const rm = (a0 + b0) / 2;
  const patchC = M3(rm * Math.cos(tc), rm * Math.sin(tc), 0.03);
  A.rspdt = scr(2.45, -0.10, 0.5);
  gAnnIn.add(leader(A.rspdt, patchC, 0.30));
  addFrame(A.rspdt);

  /* ρΔφ bracket on the outer, camera-facing (θ = t0) edge of the box */
  gAnnIn.add(lineFrom([sphPt(r1, p0, t0), sphPt(r1 + 0.34, p0, t0)], matBlack));
  gAnnIn.add(lineFrom([sphPt(r1, p1, t0), sphPt(r1 + 0.34, p1, t0)], matBlack));
  gAnnIn.add(lineFrom(samp(u => sphPt(r1 + 0.26, LERP(p0, p1, u), t0), 16), matBlack));
  A.rdphi = sphPt(r1 + 0.34, pc, t0);

  /* ===== enlarged inset ===== */
  const centre = sphPt(rc, pc, tc);
  const rad = Math.max(0.20, sphPt(r1, p0, t0).distanceTo(centre)) * 1.05;
  const S = THREE.MathUtils.clamp(IN_RAD / rad, 2.0, 4.2);
  gInset.position.copy(INSET_W);
  gInset.scale.setScalar(S);
  const inner = new THREE.Group();
  inner.position.copy(centre).multiplyScalar(-1);
  gInset.add(inner);
  inner.add(new THREE.Mesh(boxGeom(r0, r1, p0, p1, t0, t1, 11), [matBase, matTop, matSide]));
  inner.add(new THREE.LineSegments(boxEdgeGeom(r0, r1, p0, p1, t0, t1, 22), matEdge));
  for (const k of ['rho', 'phi', 'theta']) {
    const tube = tubeAlong(edgeFns[k], 0.030, focus === k ? matTubeH : matTubeN);
    inner.add(tube); hiTubes[k].push(tube);
    registerInteractive(tube, {
      title: edgeInfo[k].title, body: edgeInfo[k].body,
      tooltip: edgeInfo[k].title + ' — click to highlight',
      onClick: () => setFocus(focus === k ? null : k)
    });
  }
  const iw = (p) => p.clone().sub(centre).multiplyScalar(S).add(INSET_W);

  const mRho = iw(edgeFns.rho(0.5)), mPhi = iw(edgeFns.phi(0.5)), mThe = iw(edgeFns.theta(0.5));
  A.iRho = scr(IN_SX - 2.00, IN_SY - 0.45, IN_DEPTH);
  A.iPhi = scr(IN_SX - 1.85, IN_SY + 0.95, IN_DEPTH);
  A.iThe = scr(IN_SX + 0.75, IN_SY + 1.85, IN_DEPTH);
  gAnnOut.add(leader(A.iRho, mRho, 0.36));
  gAnnOut.add(leader(A.iPhi, mPhi, 0.36));
  gAnnOut.add(leader(A.iThe, mThe, 0.36));
  A.cap = scr(IN_SX, IN_SY - 2.00, IN_DEPTH);

  if (labelsReady) syncLabelPositions();
  updateReadout();
}

/* ---------- labels --------------------------------------------------------- */
const focusable = [];
function mkFocusLabel(base, pos, key, opt) {
  const e = addLabel(base, pos, opt);
  e.base = base; e.fkey = key; focusable.push(e);
  return e;
}
const LB = {};
function captionHTML() {
  const w = (k, s) => (focus === k ? `<b style="color:${HIC}">${s}</b>` : s);
  return `Δ<i>V</i> = <i>ρ</i><sup>2</sup> sin <i>φ</i> ` +
    `${w('rho', 'Δ<i>ρ</i>')} ${w('phi', 'Δ<i>φ</i>')} ${w('theta', 'Δ<i>θ</i>')}`;
}
function mkLabels() {
  LB.x = addLabel('<i>x</i>', M3(AX + 0.22, 0, 0), { bold: true, fontSize: '16px', offset: [-4, 12] });
  LB.y = addLabel('<i>y</i>', M3(0, AX + 0.22, 0), { bold: true, fontSize: '16px', offset: [6, 12] });
  LB.z = addLabel('<i>z</i>', M3(0, 0, AX + 0.22), { bold: true, fontSize: '16px', offset: [-12, -2] });

  LB.dRho = mkFocusLabel('Δ<i>ρ</i>', A.dRho, 'rho', { fontSize: '14px', offset: [-20, 0] });
  LB.dPhi = addLabel('Δ<i>φ</i>', A.dPhi, { fontSize: '14px', offset: [-26, -4] });
  LB.dTheta = addLabel('Δ<i>θ</i>', A.dTheta, { fontSize: '14px', offset: [-16, 2] });
  LB.rsp = addLabel('<i>ρ</i> sin <i>φ</i>', A.rsp, { fontSize: '14px', offset: [-8, 22] });
  LB.rspdt = mkFocusLabel('<i>ρ</i> sin <i>φ</i> Δ<i>θ</i>', A.rspdt, 'theta', { fontSize: '14px', offset: [44, -6] });
  LB.rdphi = mkFocusLabel('<i>ρ</i>Δ<i>φ</i>', A.rdphi, 'phi', { fontSize: '14px', offset: [24, -10] });

  LB.iRho = mkFocusLabel('Δ<i>ρ</i>', A.iRho, 'rho', { fontSize: '14px', offset: [-20, 0] });
  LB.iPhi = mkFocusLabel('<i>ρ</i>Δ<i>φ</i>', A.iPhi, 'phi', { fontSize: '14px', offset: [-26, -4] });
  LB.iThe = mkFocusLabel('<i>ρ</i> sin <i>φ</i> Δ<i>θ</i>', A.iThe, 'theta', { fontSize: '14px', offset: [26, -14] });

  LB.cap = addLabel(captionHTML(), A.cap, { fontSize: '15px' });

  LB.inPlace = [LB.dRho, LB.dPhi, LB.dTheta, LB.rsp, LB.rspdt, LB.rdphi];
  LB.inset = [LB.iRho, LB.iPhi, LB.iThe];
  labelsReady = true;
}
function syncLabelPositions() {
  LB.dRho.pos.copy(A.dRho); LB.dPhi.pos.copy(A.dPhi); LB.dTheta.pos.copy(A.dTheta);
  LB.rsp.pos.copy(A.rsp); LB.rspdt.pos.copy(A.rspdt); LB.rdphi.pos.copy(A.rdphi);
  LB.iRho.pos.copy(A.iRho); LB.iPhi.pos.copy(A.iPhi); LB.iThe.pos.copy(A.iThe);
  LB.cap.pos.copy(A.cap);
}
function refreshLabelStyles() {
  for (const e of focusable) {
    e.div.innerHTML = (e.fkey === focus) ? `<b style="color:${HIC}">${e.base}</b>` : e.base;
  }
  if (LB.cap) LB.cap.div.innerHTML = captionHTML();
}

/* ---------- label mode / focus --------------------------------------------- */
function applyLabelMode() {
  const showIn = labelMode !== 'inset';
  const showOut = labelMode !== 'place';
  gAnnIn.visible = showIn;
