──────────────────────────────────────────────────────────────────────────── */

const D2R = THREE.MathUtils.degToRad;

/* ---------- camera basis solved from the source's measured axis angles ----- */
const AXA = { x: 20, z: 30 };
const _tx = Math.tan(D2R(AXA.x));
const _tz = Math.tan(D2R(AXA.z));
const EL = Math.asin(Math.sqrt(_tx * _tz));
const AZ = Math.atan(Math.sqrt(_tz / _tx));
const SR = new THREE.Vector3(Math.sin(AZ), 0, -Math.cos(AZ));                                           // screen right
const SU = new THREE.Vector3(-Math.cos(AZ) * Math.sin(EL), Math.cos(EL), -Math.sin(AZ) * Math.sin(EL)); // screen up
const CAMDIR = new THREE.Vector3(Math.cos(AZ) * Math.cos(EL), Math.sin(EL), Math.sin(AZ) * Math.cos(EL));
const scr = (sx, sy, dep = 0) => new THREE.Vector3()
  .addScaledVector(SR, sx).addScaledVector(SU, sy).addScaledVector(CAMDIR, dep);
const sX = (p) => p.dot(SR), sY = (p) => p.dot(SU);

/* ---------- math → world (math z is up; math x → lower-left) -------------- */
const M3 = (x, y, z) => new THREE.Vector3(y, z, x);
function sphPt(r, p, t) {
  const s = Math.sin(p);
  return M3(r * s * Math.cos(t), r * s * Math.sin(t), r * Math.cos(p));
}
const LERP = (a, b, u) => a + (b - a) * u;

/* ---------- layout (screen units) ----------------------------------------- */
const AX = 2.7;                                  // axis length
const IN_SX = 4.95, IN_SY = 0.90;                // inset centre on screen
const IN_DEPTH = 2.2, IN_RAD = 1.20;             // inset toward camera; target half-size
const INSET_W = scr(IN_SX, IN_SY, IN_DEPTH);
/* rotation that turns the inset so outer + side + top faces all read */
const INSET_Q = new THREE.Quaternion()
  .setFromAxisAngle(CAMDIR, 0.22)
  .multiply(new THREE.Quaternion().setFromAxisAngle(SU, 0.50))
  .multiply(new THREE.Quaternion().setFromAxisAngle(SR, 0.80));
const INSET_QI = INSET_Q.clone().invert();
const SR_L = SR.clone().applyQuaternion(INSET_QI);
const SU_L = SU.clone().applyQuaternion(INSET_QI);

/* ---------- palette & materials ------------------------------------------- */
const COL = {
  base: 0xF0A37A, top: 0xF6C4A6, side: 0xE8895F, edge: 0xE2601F,
  blue: 0x2E4B8C, blueLine: 0x142A57, gray: 0x4F4F4F, faint: 0x8A8A8A,
  sweep: 0xB3B3B3, hi: 0x14A44D
};
const HIC = '#14A44D';
const mkFace = (c) => new THREE.MeshBasicMaterial({
  color: c, transparent: true, opacity: 0.93, side: THREE.DoubleSide,
  polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
});
const matBase = mkFace(COL.base), matTop = mkFace(COL.top), matSide = mkFace(COL.side);
const matEdge = new THREE.LineBasicMaterial({ color: COL.edge });
const matDash = new THREE.LineDashedMaterial({ color: COL.gray, dashSize: 0.17, gapSize: 0.11 });
const matDashF = new THREE.LineDashedMaterial({ color: COL.faint, dashSize: 0.11, gapSize: 0.10 });
const matBlack = new THREE.LineBasicMaterial({ color: 0x111111 });
const matBlackFill = new THREE.MeshBasicMaterial({ color: 0x111111 });
const matBlue = new THREE.MeshBasicMaterial({ color: COL.blue, side: THREE.DoubleSide });
const matBlueLine = new THREE.LineBasicMaterial({ color: COL.blueLine });
const matSweep = new THREE.MeshBasicMaterial({ color: COL.sweep });
const matTubeN = new THREE.MeshBasicMaterial({ color: COL.edge });
const matTubeH = new THREE.MeshBasicMaterial({ color: COL.hi });

/* ---------- builders ------------------------------------------------------- */
function lineFrom(pts, mat) { return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat); }
function samp(fn, n) { const a = []; for (let i = 0; i <= n; i++) a.push(fn(i / n)); return a; }

/* screen-space thickening: offset a polyline perpendicular to itself */
function offsetPts(pts, w, R, U) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
    let tx = b.dot(R) - a.dot(R), ty = b.dot(U) - a.dot(U);
    const L = Math.hypot(tx, ty) || 1; tx /= L; ty /= L;
    out.push(pts[i].clone().addScaledVector(R, -ty * w).addScaledVector(U, tx * w));
  }
  return out;
}
/* frame = {R,U,s} for content inside a rotated/scaled group */
function addBold(group, pts, mat, w, frame) {
  const R = frame ? frame.R : SR, U = frame ? frame.U : SU;
  const ww = frame ? w / frame.s : w;
  const mk = (p) => {
    const l = lineFrom(p, mat);
    if (mat.isLineDashedMaterial) l.computeLineDistances();
    group.add(l);
  };
  mk(pts);
  if (ww > 0) { mk(offsetPts(pts, ww, R, U)); mk(offsetPts(pts, -ww, R, U)); }
}
function arrowTo(from, to, headLen = 0.22, headR = 0.068, lineMat = matBlack, fillMat = matBlackFill) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length(); if (len < 1e-6) return g;
  dir.normalize();
  addBold(g, [from, to.clone().addScaledVector(dir, -headLen * 0.9)], lineMat, 0.008);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 16), fillMat);
  cone.position.copy(to).addScaledVector(dir, -headLen / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  g.add(cone);
  return g;
}
function leader(anchor, target, gap = 0.34) {
  const dir = new THREE.Vector3().subVectors(target, anchor).normalize();
  return arrowTo(anchor.clone().addScaledVector(dir, gap), target);
}
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const c = g.children[i]; g.remove(c);
    c.traverse(o => { if (o.geometry) o.geometry.dispose(); });
  }
}
function boxGeom(r0, r1, p0, p1, t0, t1, N) {
  const pos = [], groups = [];
  const faces = [
    [(u, v) => sphPt(r0, LERP(p0, p1, u), LERP(t0, t1, v)), 0],   // inner
    [(u, v) => sphPt(r1, LERP(p0, p1, u), LERP(t0, t1, v)), 0],   // outer
    [(u, v) => sphPt(LERP(r0, r1, u), p0, LERP(t0, t1, v)), 1],   // top (φ0)
    [(u, v) => sphPt(LERP(r0, r1, u), p1, LERP(t0, t1, v)), 0],   // bottom
    [(u, v) => sphPt(LERP(r0, r1, u), LERP(p0, p1, v), t0), 2],   // near side
    [(u, v) => sphPt(LERP(r0, r1, u), LERP(p0, p1, v), t1), 0]
  ];
  for (const [f, mi] of faces) {
    const start = pos.length / 3;
    for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
      const a = f(i / N, j / N), b = f((i + 1) / N, j / N), c = f((i + 1) / N, (j + 1) / N), e = f(i / N, (j + 1) / N);
      pos.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z, a.x, a.y, a.z, c.x, c.y, c.z, e.x, e.y, e.z);
    }
    groups.push([start, pos.length / 3 - start, mi]);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  groups.forEach(([s, c, m]) => g.addGroup(s, c, m));
  g.computeVertexNormals();
  return g;
}
function boxEdgePolys(r0, r1, p0, p1, t0, t1, N) {
  const out = [];
  for (const r of [r0, r1]) for (const t of [t0, t1]) out.push(samp(u => sphPt(r, LERP(p0, p1, u), t), N));
  for (const r of [r0, r1]) for (const p of [p0, p1]) out.push(samp(u => sphPt(r, p, LERP(t0, t1, u)), N));
  for (const p of [p0, p1]) for (const t of [t0, t1]) out.push(samp(u => sphPt(LERP(r0, r1, u), p, t), 1));
  return out;
}
function patchGeom(a, b, t0, t1, N) {
  const pos = [], P = (r, t) => M3(r * Math.cos(t), r * Math.sin(t), 0.006);
  for (let j = 0; j < N; j++) {
    const tA = LERP(t0, t1, j / N), tB = LERP(t0, t1, (j + 1) / N);
    const p1 = P(a, tA), p2 = P(b, tA), p3 = P(b, tB), p4 = P(a, tB);
    pos.push(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z, p3.x, p3.y, p3.z,
      p1.x, p1.y, p1.z, p3.x, p3.y, p3.z, p4.x, p4.y, p4.z);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  return g;
}
function tubeAlong(fn, radius, mat) {
  const curve = new THREE.CatmullRomCurve3(samp(fn, 16));
  return new THREE.Mesh(new THREE.TubeGeometry(curve, 24, radius, 8, false), mat);
}

/* ---------- framing: explicit screen-space extent --------------------------- */
const framePts = [];
const addFrame = (p) => { framePts.push(p.clone()); return p; };

/* ---------- static axes ---------------------------------------------------- */
const gStatic = new THREE.Group(); scene.add(gStatic);
[M3(AX, 0, 0), M3(0, AX, 0), M3(0, 0, AX)].forEach((end) => {
  const dir = end.clone().normalize();
  addBold(gStatic, [new THREE.Vector3(0, 0, 0), end.clone().addScaledVector(dir, -0.2)], matBlack, 0.009);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.24, 16), matBlackFill);
  cone.position.copy(end).addScaledVector(dir, -0.12);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  gStatic.add(cone);
  addFrame(end.clone().multiplyScalar(1.14));
});
gStatic.add(new THREE.Mesh(new THREE.SphereGeometry(0.045, 12, 10), matBlackFill));
addFrame(new THREE.Vector3(0, 0, 0));

/* ---------- groups --------------------------------------------------------- */
const gGeom = new THREE.Group(); scene.add(gGeom);     // boxes / guides / patch
const gAnnIn = new THREE.Group(); scene.add(gAnnIn);   // in-place annotations
const gAnnOut = new THREE.Group(); scene.add(gAnnOut); // inset annotations
const gInset = new THREE.Group(); scene.add(gInset);   // enlarged copy
const gSweep = new THREE.Group(); scene.add(gSweep);   // gray sweep arrow

/* gray sweep arrow: above the in-place box, up and over, head down-right, clear of the inset */
(function () {
  const a = scr(1.05, 2.35, 2.6), c = scr(2.45, 3.25, 2.6), b = scr(3.55, 2.72, 2.6);
  const curve = new THREE.QuadraticBezierCurve3(a, c, b);
  gSweep.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 48, 0.085, 10, false), matSweep));
  const tan = curve.getTangent(1).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.24, 0.58, 18), matSweep);
  head.position.copy(b).addScaledVector(tan, 0.19);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  gSweep.add(head);
  [a, c, b].forEach(addFrame);
  addFrame(scr(3.9, 2.55, 0));
})();

/* static frame hints for the inset block and its labels / caption */
addFrame(scr(IN_SX - 2.55, IN_SY + 0.9));
addFrame(scr(IN_SX - 2.45, IN_SY - 1.35));
addFrame(scr(IN_SX + 2.30, IN_SY + 1.85));
addFrame(scr(IN_SX + 1.20, IN_SY - 1.15));
addFrame(scr(IN_SX - 1.60, IN_SY - 2.05));
addFrame(scr(IN_SX + 1.70, IN_SY - 2.05));

/* ---------- state ---------------------------------------------------------- */
const params = {
  rho: 2.1, dRho: 0.45,
  phi: D2R(40), dPhi: 0.42,
  theta: D2R(50), dTheta: 0.42
};
let labelMode = 'both', focus = null, labelsReady = false, tween = null;
let hiTubes = { rho: [], phi: [], theta: [] };
const A = {};   // label anchors

/* in-place extents over the slider range, so steps never leave the frame */
for (const rr of [params.rho, params.rho + 1.2])
  for (const pp of [params.phi, params.phi + 0.7])
    for (const tt of [params.theta, params.theta + 0.7])
      addFrame(sphPt(rr + 0.45, pp, tt));
addFrame(scr(2.75, -0.55));    // ρ sin φ Δθ label
addFrame(scr(-1.35, -1.25));   // Δθ label

/* ---------- rebuild -------------------------------------------------------- */
function rebuild() {
  const { rho, dRho, phi, dPhi, theta, dTheta } = params;
  const r0 = rho, r1 = rho + dRho, p0 = phi, p1 = phi + dPhi, t0 = theta, t1 = theta + dTheta;
  const rc = (r0 + r1) / 2, pc = (p0 + p1) / 2, tc = (t0 + t1) / 2;

  [gGeom, gAnnIn, gAnnOut, gInset].forEach(clearGroup);
  _interactiveObjects.length = 0;
