    phi: u => sphPt(r1, LERP(p0, p1, u), t0),
    theta: u => sphPt(r1, p0, LERP(t0, t1, u))
  };
  const edgeInfo = {
    rho: { title: 'Radial edge: Δρ', body: 'Moving outward along ρ with φ and θ fixed traces a straight segment of length exactly Δρ — ρ is measured in distance units, so no extra factor appears.' },
    phi: { title: 'Polar edge: ρΔφ', body: 'Changing φ with ρ and θ fixed traces an arc of the circle of radius ρ, so the edge length is ρΔφ. The same angle gives a longer edge farther from the origin.' },
    theta: { title: 'Azimuthal edge: ρ sin φ Δθ', body: 'Changing θ sweeps the point around the z-axis on a circle of radius ρ sin φ (its distance from the axis), so the edge length is ρ sin φ Δθ — it collapses near the poles.' }
  };
  for (const k of ['rho', 'phi', 'theta']) {
    const tube = tubeAlong(edgeFns[k], 0.034, focus === k ? matTubeH : matTubeN);
    gGeom.add(tube); hiTubes[k].push(tube);
    registerInteractive(tube, {
      title: edgeInfo[k].title, body: edgeInfo[k].body,
      tooltip: edgeInfo[k].title + ' — click to highlight',
      onClick: () => setFocus(focus === k ? null : k)
    });
  }

  /* --- dashed meridian arcs at r0 and r1 (θ = t0 plane) --- */
  for (const r of [r0, r1])
    addBold(gGeom, samp(u => sphPt(r, LERP(0.02, Math.PI / 2 - 0.005, u), t0), 64), matDash, 0.009);
  /* --- dashed φ rays through both cone faces --- */
  for (const p of [p0, p1])
    addBold(gGeom, samp(u => sphPt(LERP(0.06, 2.95, u), p, t0), 2), matDash, 0.009);
  /* --- dashed θ rays in the xy-plane through the patch --- */
  for (const t of [t0, t1])
    addBold(gGeom, samp(u => M3(LERP(0.06, 2.45, u) * Math.cos(t), LERP(0.06, 2.45, u) * Math.sin(t), 0), 2), matDash, 0.009);

  /* --- blue projection patch + bold outline --- */
  const a0 = r0 * Math.sin(p0), b0 = r1 * Math.sin(p0);
  gGeom.add(new THREE.Mesh(patchGeom(a0, b0, t0, t1, 14), matBlue));
  const ring = samp(u => M3(a0 * Math.cos(LERP(t0, t1, u)), a0 * Math.sin(LERP(t0, t1, u)), 0.014), 14)
    .concat(samp(u => M3(b0 * Math.cos(LERP(t1, t0, u)), b0 * Math.sin(LERP(t1, t0, u)), 0.014), 14));
  ring.push(ring[0].clone());
  addBold(gGeom, ring, matBlueLine, 0.010);

  /* --- drop lines from the φ0 face corners onto the patch corners --- */
  for (const r of [r0, r1]) for (const t of [t0, t1]) {
    addBold(gGeom, [sphPt(r, p0, t),
      M3(r * Math.sin(p0) * Math.cos(t), r * Math.sin(p0) * Math.sin(t), 0)], matDashF, 0);
  }

  /* ===== in-place annotations ===== */
  const LEFT = SR.clone().multiplyScalar(-1);            // screen-left, world direction

  /* Δρ bracket on the z-axis */
  const zIn = M3(0, 0, r0), zOut = M3(0, 0, r1);
  addBold(gAnnIn, [zIn, zIn.clone().addScaledVector(LEFT, 0.62)], matBlack, 0.008);
  addBold(gAnnIn, [zOut, zOut.clone().addScaledVector(LEFT, 0.62)], matBlack, 0.008);
  addBold(gAnnIn, [zIn.clone().addScaledVector(LEFT, 0.50), zOut.clone().addScaledVector(LEFT, 0.50)], matBlack, 0.008);
  A.dRho = M3(0, 0, rc).addScaledVector(LEFT, 0.64);

  /* Δφ arc at the origin, between the two φ rays */
  addBold(gAnnIn, samp(u => sphPt(1.00, LERP(p0, p1, u), t0), 24), matBlack, 0.008);
  A.dPhi = sphPt(1.00, pc, t0);

  /* Δθ arc in the xy-plane + short leader to its label */
  const arcT = samp(u => { const t = LERP(t0, t1, u); return M3(0.90 * Math.cos(t), 0.90 * Math.sin(t), 0); }, 20);
  addBold(gAnnIn, arcT, matBlack, 0.008);
  const tMid = M3(0.90 * Math.cos(tc), 0.90 * Math.sin(tc), 0);
  A.dTheta = tMid.clone().addScaledVector(LEFT, 1.05);
  addBold(gAnnIn, [A.dTheta.clone().addScaledVector(SR, 0.24), tMid], matBlack, 0.007);

  /* ρ sin φ bracket in the xy-plane (origin → patch), with end ticks */
  const tb = t0 - 0.18;
  const O = M3(0, 0, 0), E = M3(a0 * Math.cos(tb), a0 * Math.sin(tb), 0);
  const perp = new THREE.Vector3().subVectors(E, O).normalize().cross(new THREE.Vector3(0, 1, 0)).multiplyScalar(0.19);
  addBold(gAnnIn, [O, E], matBlack, 0.008);
  addBold(gAnnIn, [O.clone().sub(perp), O.clone().add(perp)], matBlack, 0.008);
  addBold(gAnnIn, [E.clone().sub(perp), E.clone().add(perp)], matBlack, 0.008);
  A.rsp = O.clone().lerp(E, 0.55).addScaledVector(LEFT, 0.42);

  /* bracket beneath the blue patch (its outer edge) */
  const P1 = M3(b0 * Math.cos(t0), b0 * Math.sin(t0), 0), P2 = M3(b0 * Math.cos(t1), b0 * Math.sin(t1), 0);
  const Q = (r, t) => M3(r * Math.cos(t), r * Math.sin(t), 0);
  addBold(gAnnIn, [P1, Q(b0 + 0.30, t0)], matBlack, 0.007);
  addBold(gAnnIn, [P2, Q(b0 + 0.30, t1)], matBlack, 0.007);
  addBold(gAnnIn, samp(u => Q(b0 + 0.24, LERP(t0, t1, u)), 12), matBlack, 0.007);

  /* leader arrow into the blue patch */
  const rm = (a0 + b0) / 2;
  const patchC = M3(rm * Math.cos(tc), rm * Math.sin(tc), 0.03);
  A.rspdt = scr(2.62, -0.42, 0.5);
  gAnnIn.add(leader(A.rspdt, patchC, 0.34));

  /* ρΔφ bracket on the outer, camera-facing (θ = t0) edge of the box */
  addBold(gAnnIn, [sphPt(r1, p0, t0), sphPt(r1 + 0.32, p0, t0)], matBlack, 0.007);
  addBold(gAnnIn, [sphPt(r1, p1, t0), sphPt(r1 + 0.32, p1, t0)], matBlack, 0.007);
  addBold(gAnnIn, samp(u => sphPt(r1 + 0.24, LERP(p0, p1, u), t0), 14), matBlack, 0.007);
  A.rdphi = sphPt(r1 + 0.34, pc, t0);

  /* ===== enlarged inset ===== */
  const centre = sphPt(rc, pc, tc);
  const rad = Math.max(0.18, sphPt(r1, p0, t0).distanceTo(centre));
  const S = THREE.MathUtils.clamp(IN_RAD / rad, 1.5, 3.0);
  gInset.position.copy(INSET_W);
  gInset.quaternion.copy(INSET_Q);
  gInset.scale.setScalar(S);
  const inner = new THREE.Group();
  inner.position.copy(centre).multiplyScalar(-1);
  gInset.add(inner);
  const frameL = { R: SR_L, U: SU_L, s: S };
  inner.add(new THREE.Mesh(boxGeom(r0, r1, p0, p1, t0, t1, 9), [matBase, matTop, matSide]));
  for (const poly of boxEdgePolys(r0, r1, p0, p1, t0, t1, 16)) addBold(inner, poly, matEdge, 0.007, frameL);
  for (const k of ['rho', 'phi', 'theta']) {
    const tube = tubeAlong(edgeFns[k], 0.030, focus === k ? matTubeH : matTubeN);
    inner.add(tube); hiTubes[k].push(tube);
    registerInteractive(tube, {
      title: edgeInfo[k].title, body: edgeInfo[k].body,
      tooltip: edgeInfo[k].title + ' — click to highlight',
      onClick: () => setFocus(focus === k ? null : k)
    });
  }
  /* local → world for inset points */
  const iw = (p) => p.clone().sub(centre).applyQuaternion(INSET_Q).multiplyScalar(S).add(INSET_W);
  /* label anchors radiate outward from the inset centre → leaders never cross */
  function anchorFor(mid, pad) {
    const m = iw(mid);
    const dx = sX(m) - IN_SX, dy = sY(m) - IN_SY;
    const L = Math.hypot(dx, dy) || 1;
    return { m, a: m.clone().addScaledVector(SR, dx / L * pad).addScaledVector(SU, dy / L * pad) };
  }
  const aR = anchorFor(edgeFns.rho(0.5), 1.05);
  const aP = anchorFor(edgeFns.phi(0.5), 1.05);
  const aT = anchorFor(edgeFns.theta(0.5), 0.95);
  A.iRho = aR.a; A.iPhi = aP.a; A.iThe = aT.a;
  gAnnOut.add(leader(A.iRho, aR.m, 0.30));
  gAnnOut.add(leader(A.iPhi, aP.m, 0.30));
  gAnnOut.add(leader(A.iThe, aT.m, 0.30));
  A.cap = scr(IN_SX, IN_SY - 1.95, IN_DEPTH);

  if (labelsReady) syncLabelPositions();
  updateReadout();
}

/* ---------- labels --------------------------------------------------------- */
const focusable = [];
function mkFocusLabel(base, pos, key, opt) {
  const e = addLabel(base, pos, opt);
  e.base = base; e.fkey = key; focusable.push(e);
  return e;
}
const LB = {};
function captionHTML() {
  const w = (k, s) => (focus === k ? `<b style="color:${HIC}">${s}</b>` : s);
  return `Δ<i>V</i> = <i>ρ</i><sup>2</sup> sin <i>φ</i> ` +
    `${w('rho', 'Δ<i>ρ</i>')} ${w('phi', 'Δ<i>φ</i>')} ${w('theta', 'Δ<i>θ</i>')}`;
}
function mkLabels() {
  LB.x = addLabel('<i>x</i>', M3(AX + 0.22, 0, 0), { bold: true, fontSize: '16px', offset: [-4, 12] });
  LB.y = addLabel('<i>y</i>', M3(0, AX + 0.22, 0), { bold: true, fontSize: '16px', offset: [6, 12] });
  LB.z = addLabel('<i>z</i>', M3(0, 0, AX + 0.24), { bold: true, fontSize: '16px', offset: [-12, -2] });

  LB.dRho = mkFocusLabel('Δ<i>ρ</i>', A.dRho, 'rho', { fontSize: '14px', offset: [-20, 0] });
  LB.dPhi = addLabel('Δ<i>φ</i>', A.dPhi, { fontSize: '14px', offset: [-28, -2] });
  LB.dTheta = addLabel('Δ<i>θ</i>', A.dTheta, { fontSize: '14px', offset: [-16, 2] });
  LB.rsp = addLabel('<i>ρ</i> sin <i>φ</i>', A.rsp, { fontSize: '14px', offset: [-14, 16] });
  LB.rspdt = mkFocusLabel('<i>ρ</i> sin <i>φ</i> Δ<i>θ</i>', A.rspdt, 'theta', { fontSize: '14px', offset: [46, -4] });
  LB.rdphi = mkFocusLabel('<i>ρ</i>Δ<i>φ</i>', A.rdphi, 'phi', { fontSize: '14px', offset: [26, -10] });

  LB.iRho = mkFocusLabel('Δ<i>ρ</i>', A.iRho, 'rho', { fontSize: '14px', offset: [-22, -2] });
  LB.iPhi = mkFocusLabel('<i>ρ</i>Δ<i>φ</i>', A.iPhi, 'phi', { fontSize: '14px', offset: [-26, 6] });
  LB.iThe = mkFocusLabel('<i>ρ</i> sin <i>φ</i> Δ<i>θ</i>', A.iThe, 'theta', { fontSize: '14px', offset: [34, -8] });

  LB.cap = addLabel(captionHTML(), A.cap, { fontSize: '15px' });

  LB.inPlace = [LB.dRho, LB.dPhi, LB.dTheta, LB.rsp, LB.rspdt, LB.rdphi];
  LB.inset = [LB.iRho, LB.iPhi, LB.iThe];
  labelsReady = true;
}
function syncLabelPositions() {
  LB.dRho.pos.copy(A.dRho); LB.dPhi.pos.copy(A.dPhi); LB.dTheta.pos.copy(A.dTheta);
  LB.rsp.pos.copy(A.rsp); LB.rspdt.pos.copy(A.rspdt); LB.rdphi.pos.copy(A.rdphi);
  LB.iRho.pos.copy(A.iRho); LB.iPhi.pos.copy(A.iPhi); LB.iThe.pos.copy(A.iThe);
  LB.cap.pos.copy(A.cap);
}
function refreshLabelStyles() {
  for (const e of focusable) {
    e.div.innerHTML = (e.fkey === focus) ? `<b style="color:${HIC}">${e.base}</b>` : e.base;
  }
  if (LB.cap) LB.cap.div.innerHTML = captionHTML();
}

/* ---------- label mode / focus --------------------------------------------- */
function applyLabelMode() {
  const showIn = labelMode !== 'inset';
  const showOut = labelMode !== 'place';
  gAnnIn.visible = showIn;
  gAnnOut.visible = showOut;
  if (!labelsReady) return;
  LB.inPlace.forEach(e => e.div.style.visibility = showIn ? 'visible' : 'hidden');
  LB.inset.forEach(e => e.div.style.visibility = showOut ? 'visible' : 'hidden');
  document.getElementById('lmPlace').classList.toggle('active', labelMode === 'place');
  document.getElementById('lmInset').classList.toggle('active', labelMode === 'inset');
  document.getElementById('lmBoth').classList.toggle('active', labelMode === 'both');
}
function setFocus(k) {
  focus = k || null;
  for (const key of ['rho', 'phi', 'theta']) {
    const on = focus === key;
    hiTubes[key].forEach(m => { m.material = on ? matTubeH : matTubeN; });
  }
  document.querySelectorAll('#ui button[data-edge]').forEach(b =>
    b.classList.toggle('active', b.dataset.edge === (focus || 'none')));
  refreshLabelStyles();
}

/* ---------- readout -------------------------------------------------------- */
function updateReadout() {
  const { rho, dRho, phi, dPhi, dTheta } = params;
  const eR = dRho, eP = rho * dPhi, eT = rho * Math.sin(phi) * dTheta;
  const el = document.getElementById('readout');
  if (!el) return;
  el.innerHTML =
    `ρ = ${rho.toFixed(2)}, φ = ${(phi * 180 / Math.PI).toFixed(0)}°<br>` +
    `Δρ = <b>${eR.toFixed(3)}</b> &nbsp; ρΔφ = <b>${eP.toFixed(3)}</b><br>` +
    `ρ sin φ Δθ = <b>${eT.toFixed(3)}</b><br>` +
    `ΔV ≈ ${(eR * eP * eT).toFixed(4)}`;
}

/* ---------- build, frame, label -------------------------------------------- */
rebuild();

function fitView() {
  let a = Infinity, b = -Infinity, c = Infinity, e = -Infinity;
  for (const p of framePts) {
    const x = sX(p), y = sY(p);
    a = Math.min(a, x); b = Math.max(b, x); c = Math.min(c, y); e = Math.max(e, y);
  }
  const pad = 0.34;
  a -= pad; b += pad; c -= pad; e += pad;
  const w = Math.max(b - a, 0.1), h = Math.max(e - c, 0.1);
  const asp = (canvas.clientWidth || 900) / (canvas.clientHeight || 600);
  const frac = 0.99;
  const z = Math.min(2 * d * asp * frac / w, 2 * d * frac / h);
  const tgt = SR.clone().multiplyScalar((a + b) / 2).add(SU.clone().multiplyScalar((c + e) / 2));
  setCameraView({
    projection: 'orthographic',
    axisScreenAngles: AXA,
    rollDeg: 0,
    zoom: z,
    target: [tgt.x, tgt.y, tgt.z],
    heightFraction: 0.62
  });
}
fitView();
let _fitT = null;
new ResizeObserver(() => {
  clearTimeout(_fitT);
  _fitT = setTimeout(() => { if (!_userMovedCamera) fitView(); }, 90);
}).observe(canvas);
document.getElementById('btnReset').style.display = '';

mkLabels();
applyLabelMode();
refreshLabelStyles();

/* ---------- UI wiring ------------------------------------------------------ */
const sRho = document.getElementById('sRho'), sPhi = document.getElementById('sPhi'), sThe = document.getElementById('sThe');
const vRho = document.getElementById('vRho'), vPhi = document.getElementById('vPhi'), vThe = document.getElementById('vThe');
function syncSliders() {
  sRho.value = params.dRho.toFixed(2); sPhi.value = params.dPhi.toFixed(2); sThe.value = params.dTheta.toFixed(2);
  vRho.textContent = params.dRho.toFixed(2); vPhi.textContent = params.dPhi.toFixed(2); vThe.textContent = params.dTheta.toFixed(2);
}
syncSliders();
sRho.addEventListener('input', () => { tween = null; params.dRho = +sRho.value; vRho.textContent = params.dRho.toFixed(2); rebuild(); });
sPhi.addEventListener('input', () => { tween = null; params.dPhi = +sPhi.value; vPhi.textContent = params.dPhi.toFixed(2); rebuild(); });
sThe.addEventListener('input', () => { tween = null; params.dTheta = +sThe.value; vThe.textContent = params.dTheta.toFixed(2); rebuild(); });

document.getElementById('lmPlace').addEventListener('click', () => { labelMode = 'place'; applyLabelMode(); });
document.getElementById('lmInset').addEventListener('click', () => { labelMode = 'inset'; applyLabelMode(); });
document.getElementById('lmBoth').addEventListener('click', () => { labelMode = 'both'; applyLabelMode(); });

document.querySelectorAll('#ui button[data-edge]').forEach(btn => {
  btn.addEventListener('click', () => {
    const k = btn.dataset.edge;
    setFocus(k === 'none' ? null : (focus === k ? null : k));
  });
});

/* ---------- guided steps ---------------------------------------------------- */
const STEPS = [
  {
    title: '1 · The volume element in place',
    text: 'A small curved box sits above the first octant, cut out by two spheres, two cones and two half-planes; its shadow on the xy-plane is the blue quadrilateral at distance ρ sin φ from the z-axis.',
    s: { dRho: 0.45, dPhi: 0.42, dTheta: 0.42 }, mode: 'place', focus: null
  },
  {
    title: '2 · Stretch the radial edge',
    text: 'Increasing Δρ thickens the box only outward. That edge is a straight length equal to Δρ — no ρ or sin φ appears.',
    s: { dRho: 1.0, dPhi: 0.42, dTheta: 0.42 }, mode: 'inset', focus: 'rho'
  },
  {
    title: '3 · Open the polar angle',
    text: 'Increasing Δφ sweeps the box along an arc of radius ρ. The edge length is the arc length ρΔφ, so the same angle makes a longer edge farther from the origin.',
    s: { dRho: 0.45, dPhi: 0.65, dTheta: 0.42 }, mode: 'both', focus: 'phi'
  },
  {
    title: '4 · Open the azimuthal angle',
    text: 'Increasing Δθ swings the box around the z-axis on a circle of radius ρ sin φ, so that edge measures ρ sin φ Δθ — it collapses as the box moves toward the pole.',
    s: { dRho: 0.45, dPhi: 0.42, dTheta: 0.65 }, mode: 'both', focus: 'theta'
  },
  {
    title: '5 · Multiply the three edges',
    text: 'With all three increments small the box is nearly rectangular, and its volume is the product of the edges: ΔV = (Δρ)(ρΔφ)(ρ sin φ Δθ) = ρ² sin φ Δρ Δφ Δθ.',
    s: { dRho: 0.20, dPhi: 0.15, dTheta: 0.15 }, mode: 'inset', focus: null
  }
];
let stepIdx = 0, playing = false, playTimer = null;
const stepTitle = document.getElementById('stepTitle'), stepText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  stepTitle.textContent = st.title;
  stepText.textContent = st.text;
  labelMode = st.mode; applyLabelMode();
  setFocus('focus' in st ? st.focus : focus);
  tween = {
    from: { dRho: params.dRho, dPhi: params.dPhi, dTheta: params.dTheta },
    to: st.s, t0: performance.now(), dur: 800
  };
}
function tickTween() {
  requestAnimationFrame(tickTween);
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
  params.dRho = LERP(tween.from.dRho, tween.to.dRho, e);
  params.dPhi = LERP(tween.from.dPhi, tween.to.dPhi, e);
  params.dTheta = LERP(tween.from.dTheta, tween.to.dTheta, e);
  syncSliders(); rebuild();
  if (k >= 1) tween = null;
}
tickTween();

document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnPlay').addEventListener('click', () => {
  const btn = document.getElementById('btnPlay');
  playing = !playing;
  btn.textContent = playing ? '❚❚ Pause' : '▶ Play';
  btn.classList.toggle('active', playing);
  if (playing) { goToStep(stepIdx); playTimer = setInterval(() => goToStep(stepIdx + 1), 3800); }
  else clearInterval(playTimer);
});

stepTitle.textContent = STEPS[0].title;
stepText.textContent = STEPS[0].text;
